    private val categoryValues: Map<String, Int> by lazy { values(CATEGORIES) }
    private val nameValues: Map<String, Map<String, Int>> by lazy {
        NAMES.mapKeys { (category, _) -> WorkoutStructure.snakeCase(category) }.mapValues { (_, names) -> values(names) }
    }

    /** The FIT value of category [token] ("bench_press"), or null for one the profile doesn't have. */
    fun category(token: String): Int? = categoryValues[token]

    /** The FIT value of exercise [token] within [category] (both tokens), or null for one the profile doesn't have there. */
    fun exercise(category: String, token: String): Int? = nameValues[category]?.get(token)

    private fun values(list: String): Map<String, Int> =
        list.split(',').withIndex().filter { it.value.isNotEmpty() }.associate { (i, name) -> WorkoutStructure.snakeCase(name) to i }
}
